WITH DepartmentTotals AS (SELECT dept_id, MAX(salary) max_salary, AVG(salary) avg_salary FROM employees WHERE NOT is_remote GROUP BY dept_id) SELECT departments.id, departments.location, departments.dept_name, DepartmentTotals.max_salary, DepartmentTotals.avg_salary FROM departments LEFT JOIN DepartmentTotals ON departments.id = DepartmentTotals.dept_id WHERE DepartmentTotals.max_salary >= 147000;
